  const float margin = 8.0f * FLT_EPSILON *
      (1.0f + fmaxf(fabsf(global_low), fabsf(global_high)));
  const float pivot_min = 1.0e-20f *
      (1.0f + global_high - global_low);
  if (group_lane == 0) {
    float low = global_low - margin;
    float high = global_high + margin;
    for (int iteration = 0; iteration < 18; ++iteration) {
      const float midpoint = 0.5f * (low + high);
      float pivot = d[0] - midpoint;
      if (fabsf(pivot) < pivot_min) {
        pivot = -pivot_min;
      }
      int count = pivot < 0.0f;
      for (int row = 1; row < n; ++row) {
        pivot = d[row] - midpoint - e[row - 1] * e[row - 1] / pivot;
        if (fabsf(pivot) < pivot_min) {
          pivot = -pivot_min;
        }
        count += pivot < 0.0f;
      }
      if (count <= eigen_index) {
        low = midpoint;
      } else {
        high = midpoint;
      }
    }
    const float eigenvalue = 0.5f * (low + high);
    reduction[2 + eigen_index] = eigenvalue;
    values[static_cast<int64_t>(blockIdx.x) * n + eigen_index] = eigenvalue;
  }
  __syncwarp(group_mask);
  const float eigenvalue = reduction[2 + eigen_index];

  float* factor = factors + eigen_index;
  float* eigenvector = eigenvectors + eigen_index;
  if (group_lane == 0) {
    for (int row = 0; row < n; ++row) {
      const int pattern = (row * 17 + eigen_index * 13) % 23;
      eigenvector[row * kVectorPitch] =
          static_cast<float>(pattern - 11) / 11.0f;
    }
    for (int iteration = 0; iteration < 3; ++iteration) {
      const float signed_shift = (iteration & 1) ? 1.0f : -1.0f;
      const float shifted_value = eigenvalue + signed_shift *
          2.0f * FLT_EPSILON * (1.0f + fabsf(eigenvalue));
      factor[0] = d[0] - shifted_value;
      if (fabsf(factor[0]) < pivot_min) {
        factor[0] = copysignf(pivot_min, factor[0]);
      }
      for (int row = 1; row < n; ++row) {
        const int offset = row * kVectorPitch;
        const float multiplier =
            e[row - 1] / factor[offset - kVectorPitch];
        factor[offset] = d[row] - shifted_value - multiplier * e[row - 1];
        if (fabsf(factor[offset]) < pivot_min) {
          factor[offset] = copysignf(pivot_min, factor[offset]);
        }
        eigenvector[offset] -=
            multiplier * eigenvector[offset - kVectorPitch];
      }
      eigenvector[(n - 1) * kVectorPitch] /=
          factor[(n - 1) * kVectorPitch];
      for (int row = n - 2; row >= 0; --row) {
        const int offset = row * kVectorPitch;
        eigenvector[offset] =
            (eigenvector[offset] -
             e[row] * eigenvector[offset + kVectorPitch]) /
            factor[offset];
      }
      float norm = 0.0f;
      for (int row = 0; row < n; ++row) {
        const float value = eigenvector[row * kVectorPitch];
        norm += value * value;
      }
      const float inverse_norm = rsqrtf(norm);
      for (int row = 0; row < n; ++row) {
        eigenvector[row * kVectorPitch] *= inverse_norm;
      }
    }
  }
  __syncwarp(group_mask);

  for (int column = n - 3; column >= 0; --column) {
    const int base = column + 1;
    const int size = n - base;
    float partial = group_lane == 0
        ? eigenvector[base * kVectorPitch]
        : 0.0f;
    for (int row = group_lane + 1; row < size; row += kGroupWidth) {
      partial += reflectors[column * n + base + row] *
          eigenvector[(base + row) * kVectorPitch];
    }
    for (int offset = kGroupWidth / 2; offset > 0; offset >>= 1) {
      partial += __shfl_down_sync(group_mask, partial, offset, kGroupWidth);
    }
    const float dot = __shfl_sync(group_mask, partial, 0, kGroupWidth);
    const float scale = taus[column] * dot;
    if (group_lane == 0) {
      eigenvector[base * kVectorPitch] -= scale;
    }
    for (int row = group_lane + 1; row < size; row += kGroupWidth) {
      eigenvector[(base + row) * kVectorPitch] -= scale *
          reflectors[column * n + base + row];
    }
    __syncwarp(group_mask);
  }

  for (int row = group_lane; row < n; row += kGroupWidth) {
    vectors[batch_offset + row * n + eigen_index] =
        eigenvector[row * kVectorPitch];
  }
  }
  __syncthreads();

  for (int index = tid; index < n * n; index += blockDim.x) {
    const int row = index >> 5;
    const int column = index & 31;
    float aq = 0.0f;
    for (int inner = 0; inner < n; ++inner) {
      aq = fmaf(input[batch_offset + row * n + inner],
                vectors[batch_offset + inner * n + column], aq);
    }
    const float eigenvalue =
        values[static_cast<int64_t>(blockIdx.x) * n + column];
    matrix[index] = fabsf(
        aq - vectors[batch_offset + index] * eigenvalue);
  }
  __syncthreads();

  if (tid < 32) {
    float input_norm = 0.0f;
    float off_diagonal_norm = 0.0f;
    float eigen_residual = 0.0f;
    float norm = 0.0f;
    float previous_overlap = 0.0f;
    float next_overlap = 0.0f;
    for (int source_row = 0; source_row < n; ++source_row) {
      const int index = source_row * n + tid;
      const float input_value = input[batch_offset + index];
      input_norm += fabsf(input_value);
      if (source_row != tid) {
        off_diagonal_norm += fabsf(input_value);
      }
      eigen_residual += matrix[index];
      const float vector_value = vectors[batch_offset + index];
      norm = fmaf(vector_value, vector_value, norm);
      if (tid != 0) {
        previous_overlap = fmaf(
            vector_value, vectors[batch_offset + index - 1],
            previous_overlap);
      }
      if (tid != 31) {
        next_overlap = fmaf(
            vector_value, vectors[batch_offset + index + 1], next_overlap);
      }
    }
    float orthogonal_residual = fabsf(norm - 1.0f) +
        fabsf(previous_overlap) + fabsf(next_overlap);
    const float current_value =
        values[static_cast<int64_t>(blockIdx.x) * n + tid];
    const float previous_value = tid == 0
        ? current_value
        : values[static_cast<int64_t>(blockIdx.x) * n + tid - 1];
    float minimum_gap = tid == 0
        ? FLT_MAX
        : current_value - previous_value;
    float value_scale = fabsf(current_value);
    int invalid = !isfinite(current_value) ||
        !isfinite(eigen_residual) || !isfinite(orthogonal_residual);
    for (int offset = 16; offset > 0; offset >>= 1) {
      input_norm = fmaxf(
          input_norm, __shfl_down_sync(0xffffffff, input_norm, offset));
      off_diagonal_norm = fmaxf(
          off_diagonal_norm,
          __shfl_down_sync(0xffffffff, off_diagonal_norm, offset));
      eigen_residual = fmaxf(
          eigen_residual,
          __shfl_down_sync(0xffffffff, eigen_residual, offset));
      orthogonal_residual = fmaxf(
          orthogonal_residual,
          __shfl_down_sync(0xffffffff, orthogonal_residual, offset));
      minimum_gap = fminf(
          minimum_gap, __shfl_down_sync(0xffffffff, minimum_gap, offset));
      value_scale = fmaxf(
          value_scale, __shfl_down_sync(0xffffffff, value_scale, offset));
      invalid |= __shfl_down_sync(0xffffffff, invalid, offset);
    }
    if (tid == 0) {
      const float stable_value_scale = fmaxf(value_scale, 1.0e-30f);
      const float eigen_limit =
          0.5f * 200.0f * 32.0f * FLT_EPSILON * input_norm;
      const float orthogonal_limit =
          0.5f * 100.0f * 32.0f * FLT_EPSILON;
      const float gap_limit =
          256.0f * FLT_EPSILON * stable_value_scale;
      const bool scale_unsafe = input_norm != 0.0f &&
          (input_norm > 0x1p32f || input_norm < 0x1p-32f);
      const bool fused_unsafe = invalid || minimum_gap <= gap_limit ||
          eigen_residual > eigen_limit ||
          orthogonal_residual > orthogonal_limit || scale_unsafe;
      solve_modes[blockIdx.x] = off_diagonal_norm == 0.0f
          ? 2
          : (fused_unsafe ? 1 : 0);
    }
  }
}

__global__ void selective_cyclic_jacobi32(
    const float* input, float* vectors, float* values,
    const int* solve_modes, int rounds) {
  using WarpSort = cub::WarpMergeSort<float, 1, 32, int>;
  __shared__ float matrix[32 * 32];
  __shared__ float matrix_next[32 * 32];
  __shared__ float eigenvectors[32 * 32];
  __shared__ float eigenvectors_next[32 * 32];
  __shared__ float rotation_c[32];
  __shared__ float rotation_s[32];

}  // namespace

std::vector<torch::Tensor> jacobi32(torch::Tensor input) {
  TORCH_CHECK(input.is_cuda(), "input must be a CUDA tensor");
  TORCH_CHECK(input.scalar_type() == torch::kFloat32, "input must be FP32");
  TORCH_CHECK(input.dim() == 3 && input.size(1) == 32 && input.size(2) == 32,
              "jacobi32 requires shape [batch, 32, 32]");
  const c10::cuda::CUDAGuard device_guard(input.device());
  const int batch = static_cast<int>(input.size(0));
  auto vectors = torch::empty_like(input);
  auto values = torch::empty({input.size(0), 32}, input.options());
  auto solve_modes = torch::empty(
      {input.size(0)}, input.options().dtype(torch::kInt32));
  constexpr int shared_bytes = 4896 * sizeof(float);
  cudaFuncSetAttribute(fused_householder_eigh32,
                       cudaFuncAttributeMaxDynamicSharedMemorySize,
                       shared_bytes);
  fused_householder_eigh32<<<batch, 512, shared_bytes>>>(
      input.data_ptr<float>(), vectors.data_ptr<float>(),
      values.data_ptr<float>(), solve_modes.data_ptr<int>());
  selective_cyclic_jacobi32<<<batch, 1024>>>(
      input.data_ptr<float>(), vectors.data_ptr<float>(),
      values.data_ptr<float>(), solve_modes.data_ptr<int>(), 310);
  return {vectors, values};
}

torch::Tensor certify_eigh(
    torch::Tensor input, torch::Tensor vectors, torch::Tensor values) {
  TORCH_CHECK(input.is_cuda() && vectors.is_cuda() && values.is_cuda(),
              "certificate inputs must be CUDA tensors");
  TORCH_CHECK(input.scalar_type() == torch::kFloat32 &&
              vectors.scalar_type() == torch::kFloat32 &&
              values.scalar_type() == torch::kFloat32,
              "certificate inputs must be FP32");
  TORCH_CHECK(input.is_contiguous() && vectors.is_contiguous() &&
              values.is_contiguous(), "certificate inputs must be contiguous");
  const c10::cuda::CUDAGuard device_guard(input.device());
  const int batch = static_cast<int>(input.size(0));
  const int n = static_cast<int>(input.size(1));
  CertificateState& state = certificate_state();
  if (state.device != input.get_device() ||
      state.batch != batch || state.n != n) {
    state.device = input.get_device();
    state.batch = batch;
    state.n = n;
